import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define THREADS 256
#define WARPS_PER_BLOCK (THREADS / 32)

__device__ __forceinline__ float warpReduceSum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffffu, val, offset);
    return val;
}
// C = A * B, with A of shape (M, K) and B of shape (K, 1).
// K is huge, so use split-K: grid.y partitions K and each block computes a
// partial row dot product over one K-chunk. A tiny second kernel reduces the
// per-row partials.
__global__ void matvec_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              long K,
                              int vec4,
                              long chunk_len) {
    const long row = blockIdx.x;
    const long split = blockIdx.y;
    const float* aRow = A + row * K;
    const long k_begin = split * chunk_len;
    const long k_end = (k_begin + chunk_len < K) ? (k_begin + chunk_len) : K;
    const long len = k_end - k_begin;
    float sum = 0.0f;
    if (len > 0) {
        if (vec4) {
            const long len4 = len >> 2;
            const long base4 = k_begin >> 2;
            const float4* a4 = reinterpret_cast<const float4*>(aRow);
            const float4* b4 = reinterpret_cast<const float4*>(B);
            const long stride = (long)blockDim.x;
            const long step = stride << 2;
            float s0 = 0.0f, s1 = 0.0f, s2 = 0.0f, s3 = 0.0f;
            long i = (long)threadIdx.x;
            for (; i + 3L * stride < len4; i += step) {
                const long idx0 = base4 + i;
                const float4 a0 = a4[idx0];
                const float4 b0 = b4[idx0];
                const float4 a1 = a4[idx0 + stride];
                const float4 b1 = b4[idx0 + stride];
                const float4 a2 = a4[idx0 + 2L * stride];
                const float4 b2 = b4[idx0 + 2L * stride];
                const float4 a3 = a4[idx0 + 3L * stride];
                const float4 b3 = b4[idx0 + 3L * stride];
                s0 += a0.x * b0.x + a0.y * b0.y + a0.z * b0.z + a0.w * b0.w;
                s1 += a1.x * b1.x + a1.y * b1.y + a1.z * b1.z + a1.w * b1.w;
                s2 += a2.x * b2.x + a2.y * b2.y + a2.z * b2.z + a2.w * b2.w;
                s3 += a3.x * b3.x + a3.y * b3.y + a3.z * b3.z + a3.w * b3.w;
            }
            for (; i < len4; i += stride) {
                const long idx = base4 + i;
                const float4 a = a4[idx];
                const float4 b = b4[idx];
                s0 += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
            }
            sum = ((s0 + s1) + (s2 + s3));
        } else {
            for (long i = k_begin + threadIdx.x; i < k_end; i += blockDim.x) {
                sum += aRow[i] * B[i];
            }
        }
    }
    __shared__ float shared[WARPS_PER_BLOCK];
    const int lane = threadIdx.x & 31;
    const int wid  = threadIdx.x >> 5;
    sum = warpReduceSum(sum);
    if (lane == 0) shared[wid] = sum;
    __syncthreads();
    if (wid == 0) {
        sum = (lane < WARPS_PER_BLOCK) ? shared[lane] : 0.0f;
        sum = warpReduceSum(sum);
        if (lane == 0) atomicAdd(&C[row], sum);
    }
}
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    const long M = A.size(0);
    const long K = A.size(1);
    auto C = torch::zeros({M, 1}, A.options());
    const int vec4 = ((K & 3) == 0) ? 1 : 0;
    int splits = (K >= (1L << 20)) ? 8 : 1;
    if (splits > 32) splits = 32;
    long chunk_len = (K + splits - 1) / splits;
    if (vec4) chunk_len = (chunk_len + 3) & ~3L;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    dim3 grid((unsigned int)M, (unsigned int)splits);
    matvec_kernel<<<grid, THREADS, 0, stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        K,
        vec4,
        chunk_len);
    return C;
}
"""

cpp_source = "torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);"

matvec_module = load_inline(
    name="matvec_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matvec_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom CUDA kernel.
    A: (M, K), B: (K, 1) -> C: (M, 1)
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        out_device = A.device

        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()

        A = A.contiguous().float()
        B = B.contiguous().float()

        C = matvec_module.matvec_cuda(A, B)
        return C.to(out_device)

